//! Ruby extension for `lib/textkit/`, generated by everything-rust from `src/port.rs`. Regenerate with
//! `everything-rust refresh`. Values convert directly between Ruby and Rust: no JSON.

use magnus::{Error, ExceptionClass, Module, Object, Ruby, function, method};
#[allow(unused_imports)]
use serde_json::Value;

pub mod port;

/// Batches allocate on all cores at once; mimalloc keeps that from serializing.
#[global_allocator]
static GLOBAL: mimalloc::MiMalloc = mimalloc::MiMalloc;

mod rbconv;

/// `Err("ArgumentError: message")` raises that exception class; otherwise a RuntimeError.
fn error(ruby: &Ruby, message: String) -> Error {
    if let Some((kind, text)) = message.split_once(": ")
        && kind.starts_with(|c: char| c.is_ascii_uppercase())
        && kind.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
        && let Ok(class) = ruby.class_object().const_get::<_, ExceptionClass>(kind)
    {
        return Error::new(class, text.to_string());
    }
    Error::new(ruby.exception_runtime_error(), message)
}

/// Runs the port; a panic becomes a RuntimeError instead of Ruby's uncatchable `fatal`.
fn guard<T>(ruby: &Ruby, f: impl FnOnce() -> Result<T, String>) -> Result<T, Error> {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
        Ok(result) => result.map_err(|m| error(ruby, m)),
        Err(panic) => {
            let text = panic
                .downcast_ref::<&str>()
                .map(ToString::to_string)
                .or_else(|| panic.downcast_ref::<String>().cloned())
                .unwrap_or_default();
            Err(Error::new(
                ruby.exception_runtime_error(),
                format!("Rust panic: {text}"),
            ))
        }
    }
}

/// `page_count`.
fn rb_page_count(ruby: &Ruby, total: i64, per_page: i64) -> Result<i64, Error> {
    guard(ruby, || port::page_count(total, per_page))
}

/// `mean`.
fn rb_mean(ruby: &Ruby, values: Vec<f64>) -> Result<Option<f64>, Error> {
    guard(ruby, || port::mean(values))
}

/// `clamp`.
fn rb_clamp(ruby: &Ruby, value: i64, low: i64, high: i64) -> Result<i64, Error> {
    guard(ruby, || port::clamp(value, low, high))
}

/// `slugify`.
fn rb_slugify(ruby: &Ruby, text: String, sep: String, max: Option<i64>) -> Result<String, Error> {
    guard(ruby, || port::slugify(text, sep, max))
}

/// `word_count`.
fn rb_word_count(ruby: &Ruby, text: String) -> Result<magnus::Value, Error> {
    guard(ruby, || port::word_count(text)).and_then(|out| rbconv::to_rb(ruby, &out))
}

/// `titleize`.
fn rb_titleize(ruby: &Ruby, text: String) -> Result<String, Error> {
    guard(ruby, || port::titleize(text))
}

/// The items of `SlugifyBatch` as the port takes them; the port runs per item. Define
/// `pub struct SlugifyIndex` in `port.rs` (with `new` and `run`) to prepare items once.
pub struct SlugifyDefaultIndex {
    items: Vec<String>,
}

impl SlugifyDefaultIndex {
    pub fn new(items: Vec<String>) -> Self {
        Self { items }
    }

    pub fn run(&self, sep: String, max: Option<i64>) -> Result<Vec<String>, String> {
        use rayon::prelude::*;
        self.items
            .par_iter()
            .map(|item| port::slugify(item.clone(), sep.clone(), max))
            .collect::<Vec<_>>()
            .into_iter()
            .collect()
    }
}

/// `slugify` over many `text` values kept in Rust: `run` maps them all in one call, on
/// all cores; `rank` returns the indexes of results >= `min`, best first.
#[magnus::wrap(
    class = "EverythingRustNativeTextkitRs::SlugifyBatch",
    free_immediately,
    size
)]
pub struct SlugifyBatch {
    inner: SlugifyDefaultIndex,
}

impl SlugifyBatch {
    fn new(ruby: &Ruby, items: Vec<String>) -> Result<Self, Error> {
        guard(ruby, || {
            Ok(Self {
                inner: SlugifyDefaultIndex::new(items),
            })
        })
    }

    fn run(
        ruby: &Ruby,
        rb_self: &Self,
        sep: String,
        max: Option<i64>,
    ) -> Result<Vec<String>, Error> {
        guard(ruby, || rb_self.inner.run(sep, max))
    }
}

