/// `page_count` over many `total` values kept in Rust: `run` maps them all in one call, on
/// all cores; `rank` returns the indexes of results >= `min`, best first.
#[magnus::wrap(
    class = "EverythingRustNativeTextkitRs::PageCountBatch",
    free_immediately,
    size
)]
pub struct PageCountBatch {
    inner: PageCountDefaultIndex,
}

impl PageCountBatch {
    fn new(ruby: &Ruby, items: Vec<i64>) -> Result<Self, Error> {
        guard(ruby, || {
            Ok(Self {
                inner: PageCountDefaultIndex::new(items),
            })
        })
    }

    fn run(ruby: &Ruby, rb_self: &Self, per_page: i64) -> Result<Vec<i64>, Error> {
        guard(ruby, || rb_self.inner.run(per_page))
    }

    fn rank(ruby: &Ruby, rb_self: &Self, per_page: i64, min: f64) -> Result<Vec<u32>, Error> {
        let out = guard(ruby, || rb_self.inner.run(per_page))?;
        let mut hits: Vec<(f64, u32)> = out
            .into_iter()
            .enumerate()
            .map(|(i, r)| (r as f64, u32::try_from(i).unwrap_or(u32::MAX)))
            .filter(|(r, _)| *r >= min)
            .collect();
        // Stable: equal results keep the items' order, as JS `sort` and Python `sorted` do.
        hits.sort_by(|a, b| b.0.total_cmp(&a.0));
        let order: Vec<u32> = hits.into_iter().map(|(_, i)| i).collect();
        Ok(order)
    }
}

/// The items of `WordCountBatch` as the port takes them; the port runs per item. Define
/// `pub struct WordCountIndex` in `port.rs` (with `new` and `run`) to prepare items once.
pub struct WordCountDefaultIndex {
    items: Vec<String>,
}

impl WordCountDefaultIndex {
    pub fn new(items: Vec<String>) -> Self {
        Self { items }
    }

    pub fn run(&self) -> Result<Vec<Value>, String> {
        use rayon::prelude::*;
        self.items
            .par_iter()
            .map(|item| port::word_count(item.clone()))
            .collect::<Vec<_>>()
            .into_iter()
            .collect()
    }
}

/// `word_count` over many `text` values kept in Rust: `run` maps them all in one call, on
/// all cores; `rank` returns the indexes of results >= `min`, best first.
#[magnus::wrap(
    class = "EverythingRustNativeTextkitRs::WordCountBatch",
    free_immediately,
    size
)]
pub struct WordCountBatch {
    inner: WordCountDefaultIndex,
}

impl WordCountBatch {
    fn new(ruby: &Ruby, items: Vec<String>) -> Result<Self, Error> {
        guard(ruby, || {
            Ok(Self {
                inner: WordCountDefaultIndex::new(items),
            })
        })
    }

    fn run(ruby: &Ruby, rb_self: &Self) -> Result<magnus::RArray, Error> {
        guard(ruby, || rb_self.inner.run()).and_then(|out| {
            let array = ruby.ary_new_capa(out.len());
            for v in &out {
                array.push(rbconv::to_rb(ruby, v)?)?;
            }
            Ok(array)
        })
    }
}

#[magnus::init(name = "textkit_rs_native")]
fn init(ruby: &Ruby) -> Result<(), Error> {
    let native = ruby.define_module("EverythingRustNativeTextkitRs")?;
    native.define_module_function("page_count", function!(rb_page_count, 2))?;
    native.define_module_function("mean", function!(rb_mean, 1))?;
    native.define_module_function("clamp", function!(rb_clamp, 3))?;
    native.define_module_function("slugify", function!(rb_slugify, 3))?;
    native.define_module_function("word_count", function!(rb_word_count, 1))?;
    native.define_module_function("titleize", function!(rb_titleize, 1))?;
    let class = native.define_class("SlugifyBatch", ruby.class_object())?;
    class.define_singleton_method("new", function!(SlugifyBatch::new, 1))?;
    class.define_method("run", method!(SlugifyBatch::run, 2))?;
    let class = native.define_class("PageCountBatch", ruby.class_object())?;
    class.define_singleton_method("new", function!(PageCountBatch::new, 1))?;
    class.define_method("run", method!(PageCountBatch::run, 1))?;
    class.define_method("rank", method!(PageCountBatch::rank, 2))?;
    let class = native.define_class("WordCountBatch", ruby.class_object())?;
    class.define_singleton_method("new", function!(WordCountBatch::new, 1))?;
    class.define_method("run", method!(WordCountBatch::run, 0))?;
    Ok(())
}
